import { readdir, readFile, stat } from "node:fs/promises";
import { dirname, extname, relative, resolve } from "node:path";

const repoRoot = resolve(import.meta.dirname, "..");
const REPO_SLUG = "fastagent-sh/fastagent";
const DISALLOWED_HOST = /(^|\.)fastagent\.sh$/i;

async function collectPackageReadmes() {
  const packagesDir = resolve(repoRoot, "packages");
  const entries = await readdir(packagesDir, { withFileTypes: true });
  const readmes = [];
  for (const entry of entries) {
    // packages/fastagent/README.md is a gitignored copy of root README.md generated by scripts/prepack.mjs.
    if (!entry.isDirectory() || entry.name === "fastagent") continue;
    const candidate = resolve(packagesDir, entry.name, "README.md");
    if (await stat(candidate).then((info) => info.isFile(), () => false)) {
      readmes.push(candidate);
    }
  }
  return readmes.sort();
}

async function collectPackageManifests() {
  const packagesDir = resolve(repoRoot, "packages");
  const entries = await readdir(packagesDir, { withFileTypes: true });
  const manifests = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const candidate = resolve(packagesDir, entry.name, "package.json");
    if (await stat(candidate).then((info) => info.isFile(), () => false)) {
      manifests.push(candidate);
    }
  }
  return manifests.sort();
}

async function docFiles(path, explicit = false) {
  const entries = await readdir(path, { withFileTypes: true }).catch(() => undefined);
  if (!entries) {
    return explicit || extname(path) === ".md" || path.endsWith(".github/ISSUE_TEMPLATE/config.yml") ? [resolve(path)] : [];
  }
  const nested = await Promise.all(
    entries
      .filter((entry) => entry.name !== "node_modules" && entry.name !== "dist")
      .map((entry) => docFiles(resolve(path, entry.name))),
  );
  return nested.flat();
}

function withoutCode(markdown) {
  let fence;
  return markdown
    .split("\n")
    .map((line) => {
      const marker = /^ {0,3}(`{3,}|~{3,})/.exec(line)?.[1];
      if (marker) {
        if (!fence) fence = marker;
        else if (marker[0] === fence[0] && marker.length >= fence.length) fence = undefined;
        return " ".repeat(line.length);
      }
      if (fence) return " ".repeat(line.length);
      return line.replace(/(`+).*?\1/g, (code) => " ".repeat(code.length));
    })
    .join("\n");
}

function anchors(markdown) {
  const seen = new Map();
  const out = new Set();
  for (const line of markdown.split("\n")) {
    const match = /^#{1,6}\s+(.+?)\s*#*$/.exec(line);
    if (!match) continue;
    const base = match[1]
      .toLowerCase()
      .replace(/<[^>]*>/g, "")
      .replace(/[^\p{L}\p{N}_ -]/gu, "")
      .trim()
      .replace(/\s+/g, "-");
    const count = seen.get(base) ?? 0;
    seen.set(base, count + 1);
    out.add(count === 0 ? base : `${base}-${count}`);
  }
  return out;
}

function resolveTarget(file, target) {
  if (!target || /^mailto:/.test(target)) return undefined;
  if (/^https?:/.test(target)) {
    const url = URL.parse(target);
    if (!url) return { invalid: `malformed URL ${target}` };
    if (DISALLOWED_HOST.test(url.hostname)) {
      return { invalid: `disallowed external fastagent.sh link ${target} (keep repository self-contained)` };
    }
    const fragment = url.hash ? url.hash.slice(1) : undefined;
    if (url.origin === "https://github.com") {
      const blobPrefix = `/${REPO_SLUG}/blob/main/`;
      const treePrefix = `/${REPO_SLUG}/tree/main/`;
      if (url.pathname.startsWith(blobPrefix)) {
        const rel = decodeURIComponent(url.pathname.slice(blobPrefix.length));
        return { targetFile: resolve(repoRoot, rel), fragment, kind: "file" };
      }
      if (url.pathname.startsWith(treePrefix)) {
        const rel = decodeURIComponent(url.pathname.slice(treePrefix.length));
        return { targetFile: resolve(repoRoot, rel), kind: "any" };
      }
      return undefined;
    }
    if (url.origin === "https://raw.githubusercontent.com") {
      const rawPrefix = `/${REPO_SLUG}/main/`;
      if (url.pathname.startsWith(rawPrefix)) {
        const rel = decodeURIComponent(url.pathname.slice(rawPrefix.length));
        return { targetFile: resolve(repoRoot, rel), kind: "file" };
      }
      return undefined;
    }
    if (url.origin === "https://cdn.jsdelivr.net") {
      const cdnPrefix = `/gh/${REPO_SLUG}@main/`;
      if (url.pathname.startsWith(cdnPrefix)) {
        const rel = decodeURIComponent(url.pathname.slice(cdnPrefix.length));
        return { targetFile: resolve(repoRoot, rel), kind: "file" };
      }
      return undefined;
    }
    return undefined;
  }
  const [pathPart, fragment] = target.split("#", 2);
  return { targetFile: resolve(dirname(file), pathPart || file), fragment, kind: "any" };
}

function extractTargets(file, prose) {
  if (extname(file) === ".yml" || extname(file) === ".yaml") {
    return Array.from(prose.matchAll(/https?:\/\/[^\s"'<>)]+/g), (match) => ({
      index: match.index,
      target: match[0].replace(/[.,;]+$/, ""),
    }));
  }
  const seen = new Set();
  const out = [];
  const push = (index, target) => {
    const key = `${index}:${target}`;
    if (seen.has(key)) return;
    seen.add(key);
    out.push({ index, target });
  };
  for (const match of prose.matchAll(/!?\[[^\]]*\]\(([^)]+)\)/g)) {
    push(match.index, match[1].trim().split(/\s+/)[0].replace(/^<|>$/g, ""));
  }
  for (const match of prose.matchAll(/<a\b[^>]*\bhref=(?:"([^"]+)"|'([^']+)')/gi)) {
    push(match.index, (match[1] ?? match[2]).trim());
  }
  for (const match of prose.matchAll(/<img\b[^>]*\bsrc=(?:"([^"]+)"|'([^']+)')/gi)) {
    push(match.index, (match[1] ?? match[2]).trim());
  }
  // Catch bare URLs in prose (e.g. coding-agent prompt blockquotes).
  for (const match of prose.matchAll(/(?<![("'=])https?:\/\/[^\s"'<>)]+/g)) {
    push(match.index, match[0].replace(/[.,;]+$/, ""));
  }
  return out;
}

const roots = [
  "README.md",
  "README.zh-CN.md",
  "CONTRIBUTING.md",
  "SECURITY.md",
  "AGENTS.md",
  "llms.txt",
  "docs",
  "examples",
  ".github",
].map((entry) => resolve(repoRoot, entry));

const files = [
  ...(await Promise.all(roots.map((root) => docFiles(root, true)))).flat(),
  ...(await collectPackageReadmes()),
].sort();

const statCache = new Map();
const textCache = new Map();
const errors = [];

for (const file of files) {
  const markdown = await readFile(file, "utf8");
  const prose = extname(file) === ".yml" || extname(file) === ".yaml" ? markdown : withoutCode(markdown);
  for (const { index, target } of extractTargets(file, prose)) {
    const resolved = resolveTarget(file, target);
    if (!resolved) continue;
    const line = markdown.slice(0, index).split("\n").length;
    const displayFile = relative(repoRoot, file);
    if (resolved.invalid) {
      errors.push(`${displayFile}:${line}: ${resolved.invalid}`);
      continue;
    }
    const { targetFile, fragment, kind } = resolved;
    let info = statCache.get(targetFile);
    if (info === undefined) {
      info = await stat(targetFile).catch(() => null);
      statCache.set(targetFile, info);
    }
    if (info === null || (kind === "file" && !info.isFile())) {
      errors.push(`${displayFile}:${line}: missing ${target}`);
      continue;
    }
    if (fragment) {
      if (!info.isFile()) {
        errors.push(`${displayFile}:${line}: anchor on non-file target ${target}`);
        continue;
      }
      let targetMarkdown = textCache.get(targetFile);
      if (targetMarkdown === undefined) {
        targetMarkdown = await readFile(targetFile, "utf8");
        textCache.set(targetFile, targetMarkdown);
      }
      if (!anchors(targetMarkdown).has(decodeURIComponent(fragment).toLowerCase())) {
        errors.push(`${displayFile}:${line}: missing anchor ${target}`);
      }
    }
  }
}

for (const manifest of await collectPackageManifests()) {
  const pkg = JSON.parse(await readFile(manifest, "utf8"));
  if (typeof pkg.homepage === "string") {
    const url = URL.parse(pkg.homepage);
    if (url && DISALLOWED_HOST.test(url.hostname)) {
      errors.push(`${relative(repoRoot, manifest)}: disallowed homepage ${pkg.homepage} (keep repository self-contained)`);
    }
  }
}

if (errors.length > 0) {
  console.error(errors.join("\n"));
  process.exitCode = 1;
} else {
  console.log(`Checked ${files.length} documentation files.`);
}
